// 승인용 정적 화면. 데이터 저장이나 G5 코어 연결은 하지 않습니다.
const params = new URLSearchParams(location.search);
const screen = params.get('screen') || 'home';
document.documentElement.dataset.theme = params.get('theme') === 'business' ? 'business' : 'corporate';
const I = (name, cls = '') => '<i data-lucide="' + name + '" class="' + cls + '"></i>';
const photo = (name, alt, cls = '') => '<img class="' + cls + '" src="./assets/' + name + '.png" alt="' + alt + '">';
const btn = (text, kind = 'primary', symbol = 'arrow-up-right', href = '#') => '<a class="btn ' + kind + '" href="' + href + '">' + text + (symbol ? I(symbol) : '') + '</a>';
const label = (text, required = false) => '<span class="field-label">' + text + (required ? '<b class="required" aria-label="필수">*</b>' : '') + '</span>';
const field = (text, id, placeholder, help = '', type = 'text', required = false) => '<label class="field" for="' + id + '">' + label(text, required) + '<input id="' + id + '" type="' + type + '" placeholder="' + placeholder + '" autocomplete="' + (type === 'password' ? 'new-password' : 'off') + '">' + (help ? '<small>' + help + '</small>' : '') + '</label>';
const check = (text, checked = false) => '<label class="checkbox"><input type="checkbox"' + (checked ? ' checked' : '') + '><span>' + text + '</span></label>';
const brand = () => '<a class="brand" href="?screen=home"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M3 28V4h6l14 16V4h6v24h-6L9 12v16z" fill="currentColor"/></svg><span>JW NEXUS<small>BUSINESS IN MOTION</small></span></a>';
const header = () => '<header class="header"><div class="header-inner">' + brand() + '<nav aria-label="주 메뉴"><a href="#">회사소개</a><a href="#business">사업영역</a><a href="#projects">프로젝트</a><a class="' + (['list','view','write'].includes(screen) ? 'selected' : '') + '" href="?screen=list">소식·자료</a><a href="#">인재채용</a></nav><div class="header-tools"><a class="account" href="?screen=register">' + I('user-round') + '<span>회원가입</span></a><button class="theme-switch icon-btn" aria-label="라이트·다크 전환">' + I(document.documentElement.dataset.theme === 'business' ? 'sun' : 'moon') + '</button>' + btn('문의하기','primary','arrow-up-right') + '<button class="mobile-menu icon-btn" aria-label="메뉴">' + I('menu') + '</button></div></div></header>';
const footer = () => '<footer class="footer"><div class="wrap footer-top">' + brand() + '<div class="footer-menu"><a href="#">회사소개</a><a href="#business">사업영역</a><a href="?screen=list">소식·자료</a><a href="#">문의하기</a></div></div><div class="wrap footer-info"><div><p>(주)제이더블유넥서스 · 대표 김지원<br>서울특별시 성동구 성수이로 00, 5층 · 사업자등록번호 000-00-00000</p><small>가상 기업·예시 수치·AI 이미지로 구성한 테마 디자인 시안입니다.</small></div><div><strong>02. 0000. 0000</strong><p>hello@example.com</p></div><div><a href="#">개인정보처리방침</a><a href="#">이용약관</a><p>© JW NEXUS. All rights reserved.</p></div></div></footer>';
