const subhero = (title, desc, active = '기업소식') => '<section class="subhero"><div class="subhero-image">' + photo('hero','도시와 바다를 연결하는 교량') + '</div><div class="wrap"><div class="crumb">' + I('house') + I('chevron-right') + '<span>소식·자료</span></div><h1>' + title + '</h1><p>' + desc + '</p></div></section><nav class="subnav wrap" aria-label="소식 메뉴">' + ['기업소식','공지사항','자료실','자주 묻는 질문'].map(x => '<a href="?screen=list" class="' + (x===active?'active':'') + '">' + x + '</a>').join('') + '</nav>';
